    private void showWhatsNewIfNeeded(){
        try {
            android.content.SharedPreferences prefs=getSharedPreferences("serein",MODE_PRIVATE);String seen=prefs.getString("whats_new_version","");
            android.content.pm.PackageInfo packageInfo=getPackageManager().getPackageInfo(getPackageName(),0);String version=(packageInfo.versionName==null?"unknown":packageInfo.versionName)+" (build "+packageInfo.versionCode+")";if(version.equals(seen))return;
            prefs.edit().putString("whats_new_version",version).apply();
            new AlertDialog.Builder(this).setTitle(seen.isEmpty()?"Welcome to Serein":"What’s new in Serein")
                    .setMessage("Version "+version+"\n\n• Email verification and stronger account safeguards.\n• Contact, privacy, and device settings.\n• Server connections can be checked and changed in Connection settings.\n• Native and web encrypted chat require explicit device-fingerprint verification.\n• Notification permissions are requested from Settings; sound is configurable per device.")
                    .setPositiveButton("Continue",null).show();
        } catch (Exception ignored) { }
    }
    private String countdownLabel(long millis){long seconds=Math.max(0,(millis+999)/1000);return String.format(java.util.Locale.ROOT,"Resend in %02d:%02d",seconds/60,seconds%60);}
    private void startResendCooldown(Button button,int seconds){int bounded=Math.max(1,Math.min(seconds,3600));button.setEnabled(false);new CountDownTimer(bounded*1000L,1000){public void onTick(long millisUntilFinished){button.setText(countdownLabel(millisUntilFinished));}public void onFinish(){button.setEnabled(true);button.setText("Resend code");}}.start();}
    private boolean hasAsciiUppercase(String value){for(int i=0;i<value.length();i++)if(value.charAt(i)>='A'&&value.charAt(i)<='Z')return true;return false;}
    private boolean hasAsciiLowercase(String value){for(int i=0;i<value.length();i++)if(value.charAt(i)>='a'&&value.charAt(i)<='z')return true;return false;}
    private boolean hasAsciiDigit(String value){for(int i=0;i<value.length();i++)if(value.charAt(i)>='0'&&value.charAt(i)<='9')return true;return false;}
    private String passwordRulesText(String value){String bytes=value.getBytes(StandardCharsets.UTF_8).length+"/1024 UTF-8 bytes";return (value.codePointCount(0,value.length())>=8?"✓":"○")+"  At least 8 characters\n"+(hasAsciiUppercase(value)?"✓":"○")+"  Uppercase A–Z\n"+(hasAsciiLowercase(value)?"✓":"○")+"  Lowercase a–z\n"+(hasAsciiDigit(value)?"✓":"○")+"  Number 0–9\n"+(value.getBytes(StandardCharsets.UTF_8).length<=1024?"✓":"○")+"  "+bytes;}
