    private void authFinished(Button button,Object result,String error,String email,String identity,String password,boolean registering){
        button.setEnabled(true);button.setText(registering?"Create account":"Sign in");
        JSONObject response=result instanceof JSONObject?(JSONObject)result:null;
        JSONObject verification=response==null?null:response.optJSONObject("verification");
        if(verification!=null&&verification.optBoolean("required")){
            String address=verification.optString("email",email).trim();
            if(!address.isEmpty())renderVerification(address,verification.optString("purpose","email"),identity,password);
            message(error!=null?error:response.optString("message","A verification code was sent to your email."));return;
        }
        if(registering&&error==null){renderVerification(email,"email",identity,password);message(response==null?"A verification code was sent to your email.":response.optString("message","A verification code was sent to your email."));return;}
        if(error!=null){message(error);return;}
        if(response==null){message("Unexpected API response.");return;}
        account=response.optJSONObject("account");if(account==null)account=response;JSONObject user=account.optJSONObject("user");if(user==null){message("Account response was incomplete.");return;}contactsLoaded=false;contacts=new JSONArray();renderMain("Chats");syncAccountPreferences();
    }
