    private void showDeleteAccountDialog(){
        JSONObject current=account==null?null:account.optJSONObject("user");if(current==null)return;String userId=current.optString("id","");
        LinearLayout form=SereinUi.column(this);form.setPadding(pad(18),pad(8),pad(18),pad(8));form.addView(paragraph("This cannot be undone. All sessions will be revoked. Type DELETE and enter your current password."));
        EditText password=new EditText(this);password.setHint("Current password");password.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setSingleLine(true);form.addView(password,SereinUi.margin(this,-1,48,0,8,0,0));
        EditText phrase=new EditText(this);phrase.setHint("Type DELETE");phrase.setSingleLine(true);form.addView(phrase,SereinUi.margin(this,-1,48,0,0,0,0));
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Permanently delete account?").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Delete",null).create();dialog.setOnShowListener(ignored->{Button confirm=dialog.getButton(AlertDialog.BUTTON_POSITIVE);confirm.setOnClickListener(button->{String secret=password.getText().toString();if(secret.isEmpty()||!"DELETE".equals(phrase.getText().toString())){message("Enter your current password and type DELETE exactly.");return;}confirm.setEnabled(false);confirm.setText("Deleting…");dialog.setCancelable(false);password.setText("");api.deleteAccount(secret,(result,error)->{if(error!=null){dialog.setCancelable(true);dialog.setCanceledOnTouchOutside(true);confirm.setEnabled(true);confirm.setText("Delete");message(error);return;}boolean historyCleared=SereinLocalStore.deleteForAccount(this,userId);boolean keysCleared=SereinDeviceCrypto.deleteForAccount(this,userId);boolean downloadsCleared=SereinAttachmentStore.deleteForAccount(this,userId);boolean localCleared=historyCleared&&keysCleared&&downloadsCleared;getSharedPreferences("serein",MODE_PRIVATE).edit().remove("serein.device-id").remove("restore_prompt_done").apply();account=null;contacts=new JSONArray();contactsLoaded=false;dialog.dismiss();renderAuth();message(localCleared?"Account deleted. Local account history and keys were cleared. Legacy downloaded files in shared storage may remain and must be deleted manually.":"Account deleted and server access revoked, but some local history or keys could not be cleared. Remove Serein app data from this device.");});});});dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setTextColor(0xffb42332);}
    private String safeHealthComponent(JSONObject components,String key){String value=components==null?"unknown":components.optString(key,"unknown").toLowerCase(java.util.Locale.ROOT);return java.util.Arrays.asList("ready","ok","available","unavailable","degraded","disabled","configured","not_configured","unknown").contains(value)?value:"unknown";}
    private void showConnectionSettings(){
        LinearLayout content=SereinUi.column(this);content.addView(paragraph("Choose the HTTPS account API origin you host or trust. Web clients also require the exact frontend origin in ALLOWED_WEB_ORIGINS. Relay transport is not available yet."),SereinUi.margin(this,-1,-2,0,0,0,9));EditText url=field("https://serein.example.com",false);url.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);url.setText(api.baseUrl());content.addView(SereinUi.label(this,"HTTPS SERVER ORIGIN"));content.addView(url,SereinUi.margin(this,-1,48,0,5,0,9));TextView status=paragraph("Current status: "+connectionStatus);content.addView(status,SereinUi.margin(this,-1,-2,0,0,0,9));
        LinearLayout actions=SereinUi.row(this);Button check=SereinUi.button(this,"Check connection",false),save=SereinUi.button(this,"Save server",true);actions.addView(check,new LinearLayout.LayoutParams(0,pad(43),1));actions.addView(save,new LinearLayout.LayoutParams(0,pad(43),1));content.addView(actions);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Server connection").setView(content).setNegativeButton("Close",null).create();dialog.setOnDismissListener(ignored->{if(account==null)renderAuth();else renderMain(activePage);});String[] tested={""};boolean[] reachable={false};
        check.setOnClickListener(v->{String candidate;try{candidate=api.normalizeBaseUrl(url.getText().toString());}catch(Exception e){status.setText(e.getMessage());connectionStatus="Invalid server URL";connectionCheckedOrigin="";return;}status.setText("Checking secure connection…");check.setEnabled(false);check.setText("Checking…");api.testConnection(candidate,(result,error)->{check.setEnabled(true);check.setText("Check connection");if(error!=null){reachable[0]=false;tested[0]="";connectionStatus="Not connected";connectionCheckedOrigin="";status.setText(error);return;}if(!(result instanceof JSONObject)){reachable[0]=false;tested[0]="";connectionStatus="Unexpected health response";connectionCheckedOrigin="";status.setText(connectionStatus);return;}JSONObject health=(JSONObject)result,components=health.optJSONObject("components");String healthValue=health.optString("status","");if((!healthValue.equals("ready")&&!healthValue.equals("degraded"))||components==null){reachable[0]=false;tested[0]="";connectionStatus="Unexpected health response";connectionCheckedOrigin="";status.setText(connectionStatus);return;}String apiState=safeHealthComponent(components,"api"),dbState=safeHealthComponent(components,"database"),frontState=safeHealthComponent(components,"frontend"),emailState=safeHealthComponent(components,"email_delivery");reachable[0]=true;tested[0]=candidate;connectionCheckedOrigin=candidate;connectionStatus=health.optString("status","unknown").equals("ready")?"Connected":"Reachable · degraded";status.setText(connectionStatus+"\nAPI: "+apiState+" · Database: "+dbState+" · Web: "+frontState+" · Email: "+emailState);});});
        save.setOnClickListener(v->{String candidate;try{candidate=api.normalizeBaseUrl(url.getText().toString());}catch(Exception e){status.setText(e.getMessage());return;}if(!reachable[0]||!candidate.equals(tested[0])){status.setText("Check this server successfully before saving it.");return;}if(candidate.equals(api.baseUrl())){dialog.dismiss();return;}if(account!=null){dialog.dismiss();new AlertDialog.Builder(this).setTitle("Switch servers?").setMessage("Switching signs you out of the current server. You can sign in again after the new server is saved.").setNegativeButton("Cancel",null).setPositiveButton("Switch",(d,w)->api.logout((r,e)->{if(e!=null){account=null;contactsLoaded=false;contacts=new JSONArray();registerMode=false;connectionStatus="Not checked";connectionCheckedOrigin="";renderAuth();message("Local session cleared, but the server did not confirm sign-out. The server choice was not changed; retry when it is reachable.");return;}api.setBaseUrl(candidate);account=null;contactsLoaded=false;contacts=new JSONArray();registerMode=false;connectionCheckedOrigin=candidate;renderAuth();message("Server changed. Sign in again to continue.");})).show();}else{api.setBaseUrl(candidate);connectionCheckedOrigin=candidate;dialog.dismiss();message("Server saved.");}});
        dialog.show();
    }
    private void showAddContact(){LinearLayout content=SereinUi.column(this);content.setPadding(pad(6),pad(6),pad(6),pad(2));content.addView(paragraph("The other person must accept before becoming a contact. The server gives the same response whether an email is eligible."));EditText input=field("Username or verified email",false);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);content.addView(input,SereinUi.margin(this,-1,48,0,10,0,4));TextView status=paragraph("");content.addView(status);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Request a connection").setView(content).setNegativeButton("Cancel",null).setPositiveButton("Send request",null).create();dialog.setOnShowListener(ignored->{Button submit=dialog.getButton(AlertDialog.BUTTON_POSITIVE);submit.setOnClickListener(view->{String identity=input.getText().toString().trim();if(identity.isEmpty()){status.setText("Enter a username or email address.");input.requestFocus();return;}submit.setEnabled(false);submit.setText("Sending…");api.addContact(identity,(result,error)->{if(error!=null){status.setText(error);submit.setEnabled(true);submit.setText("Send request");return;}dialog.dismiss();message("If the verified account is eligible, it will receive a connection request. The server does not disclose request status before acceptance.");});});});dialog.show();}
